"""Plain data objects shared by every command."""
from dataclasses import dataclass, asdict


@dataclass(frozen=True)
class ScanResult:
    host: str
    port: int
    state: str          # "open" or "closed"
    banner: str = ""

    def as_row(self):
        return asdict(self)


@dataclass(frozen=True)
class PingStats:
    host: str
    sent: int
    received: int
    loss_pct: float
    min_ms: float
    avg_ms: float
    max_ms: float

    def as_row(self):
        return asdict(self)

"""Resolve names with the OS resolver, or ask a chosen server through dig."""
import socket
import subprocess


def lookup_system(name):
    """A and AAAA records through getaddrinfo (the same path your browser uses)."""
    try:
        infos = socket.getaddrinfo(name, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror as exc:
        raise LookupError(f"{name}: {exc.strerror}") from None
    return sorted({info[4][0] for info in infos})


def lookup_dig(name, rtype="A", server=None, timeout=3):
    """Ask dig for one record type. Returns a sorted list of answer strings."""
    cmd = ["dig", "+short", f"+time={timeout}", "+tries=1"]
    if server:
        cmd.append(f"@{server}")
    cmd += [name, rtype]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout * 2 + 2)
    except FileNotFoundError:
        raise RuntimeError("dig was not found (macOS includes it; Debian: apt install dnsutils)") from None
    except subprocess.TimeoutExpired:
        raise RuntimeError(f"dig {name} timed out") from None
    return sorted(line.strip() for line in proc.stdout.splitlines() if line.strip())


def compare(name, rtype, servers):
    """Query several servers; return rows and whether every server agrees."""
    rows, answers = [], set()
    for server in servers:
        found = lookup_dig(name, rtype, server)
        rows.append({"name": name, "type": rtype, "server": server, "answer": " ".join(found) or "(none)"})
        answers.add(tuple(found))
    return rows, len(answers) == 1

"""A small threaded TCP connect scanner. Own machine and own LAN only."""
import ipaddress
import socket
from concurrent.futures import ThreadPoolExecutor

from netkit.models import ScanResult


def parse_ports(spec):
    """Expand '80,443,8000-8003' into a sorted list of unique ports."""
    ports = set()
    for part in spec.split(","):
        part = part.strip()
        if not part:
            continue
        if "-" in part:
            lo, hi = (int(x) for x in part.split("-", 1))
            if lo > hi:
                raise ValueError(f"bad range: {part}")
            ports.update(range(lo, hi + 1))
        else:
            ports.add(int(part))
    bad = [p for p in ports if not 1 <= p <= 65535]
    if bad:
        raise ValueError(f"port out of range: {min(bad)}")
    return sorted(ports)


def resolve(host):
    """Return the first IPv4 address for a name or address."""
    infos = socket.getaddrinfo(host, None, socket.AF_INET, socket.SOCK_STREAM)
    return infos[0][4][0]


def is_allowed(address):
    """True for loopback, RFC 1918 and link-local addresses."""
    ip = ipaddress.ip_address(address)
    return ip.is_loopback or ip.is_private or ip.is_link_local


def probe(address, port, timeout):
    """Try one TCP connection. connect_ex returns an errno instead of raising."""
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.settimeout(timeout)
        if s.connect_ex((address, port)) != 0:
            return ScanResult(address, port, "closed")
        banner = ""
        try:
            s.settimeout(0.3)
            banner = s.recv(128).decode("ascii", "replace").strip()
        except OSError:
            pass
        return ScanResult(address, port, "open", banner)


def scan(host, ports, timeout=0.5, workers=100, allow_public=False):
    """Scan host and return results sorted by port. Refuses public addresses by default."""
    address = resolve(host)
    if not allow_public and not is_allowed(address):
        raise PermissionError(
            f"{address} is not loopback or private. Scan only machines you own or may test."
        )
    with ThreadPoolExecutor(max_workers=workers) as pool:
        results = pool.map(lambda p: probe(address, p, timeout), ports)
    return sorted(results, key=lambda r: r.port)

import socket
import threading

import pytest

from netkit.scan import is_allowed, parse_ports, scan


@pytest.fixture
def listener():
    """A real TCP listener on an ephemeral loopback port that sends a banner."""
    srv = socket.socket()
    srv.bind(("127.0.0.1", 0))
    srv.listen()

    def serve():
        try:
            while True:
                conn, _ = srv.accept()
                conn.sendall(b"HELLO test\r\n")
                conn.close()
        except OSError:
            pass

    threading.Thread(target=serve, daemon=True).start()
    yield srv.getsockname()[1]
    srv.close()


def test_parse_ports():
    assert parse_ports("443,80,8000-8002,80") == [80, 443, 8000, 8001, 8002]


@pytest.mark.parametrize("bad", ["0", "70000", "9-3", "abc"])
def test_parse_ports_rejects(bad):
    with pytest.raises(ValueError):
        parse_ports(bad)


def test_is_allowed():
    assert is_allowed("127.0.0.1") and is_allowed("192.168.1.9") and is_allowed("169.254.1.1")
    assert not is_allowed("93.184.216.34")


def test_finds_open_port_and_banner(listener):
    results = scan("127.0.0.1", [listener], timeout=1.0)
    assert results[0].state == "open"
    assert results[0].banner == "HELLO test"


def test_closed_port(listener):
    s = socket.socket()
    s.bind(("127.0.0.1", 0))      # claim a free port, then close it so it is surely closed
    free = s.getsockname()[1]
    s.close()
    assert scan("127.0.0.1", [free], timeout=1.0)[0].state == "closed"


def test_refuses_public_address():
    with pytest.raises(PermissionError):
        scan("93.184.216.34", [80])

